<!doctype html><html lang="id"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password · Trieps</title><style>body{font:16px system-ui;background:#102b26;color:white;max-width:420px;margin:12vh auto;padding:24px}input,button{display:block;box-sizing:border-box;width:100%;padding:16px;margin:14px 0;border:0;border-radius:12px}button{background:#d7ff65;font-weight:bold}</style><h1>Password baru, perjalanan baru.</h1><form id="reset"><input type="email" name="email" value="{{ $email }}" required placeholder="Email"><input name="password" type="password" minlength="10" required placeholder="Password baru (min. 10 karakter)"><input name="password_confirmation" type="password" required placeholder="Ulangi password"><button>Simpan password</button></form><p id="message" role="status"></p><script>document.querySelector('form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));body.token=@json($token);try{const r=await fetch('/api/v1/auth/reset-password',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(body)});const d=await r.json();document.querySelector('#message').textContent=d.message||'Periksa kembali data kamu.';}catch{document.querySelector('#message').textContent='Koneksi terputus. Coba lagi.'}};</script></html>
